import StatisticsCards from "@/components/cards/StatisticsCards";
import ProgramList from "../components/programList/ProgramList";
import { Card } from "@/types/statistics";
import PeopleIcon from "@/components/icons/PeopleIcon";
import TwoUserIcon from "@/components/icons/TwoUsersIcon";
import UserMinusIcon from "@/components/icons/UserMinusIcon";
import UserRemoveIcon from "@/components/icons/UserRemoveIcon";
import { useEffect, useState } from "react";
import { endpoints } from "@/lib/axios/axios-global";
import { programsStats } from "../types/program.types";
import { apiGet } from "@/lib/axios/axios-utils";

const cards: Card[] = [
    { text: 'إجمالي البرامج', icon: <PeopleIcon />, num: 35, percent: 12 },
    { text: 'إجمالي المتدربين', icon: <TwoUserIcon />, num: 22, percent: 0 },
    { text: 'إجمالي المدفوع', icon: <UserMinusIcon />, num: 10, percent: -0.3 },
    { text: 'إجمالي المتبقي', icon: <UserRemoveIcon />, num: 3, percent: -0.3 },
];

const Programs = () => {
    const [stats, setStats] = useState<programsStats | null>(null);
    
    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.program.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    return <div className="mt-6 w-full">
        <StatisticsCards cards={cards} />
        <ProgramList />
    </div>;
};

export default Programs;
