import { ColumnDef, Row } from '@tanstack/react-table';
import { useNavigate } from 'react-router-dom';
import ViewIcon from '@/components/icons/ViewIcon';
import { Program } from '../../types/program.types';

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<Program> }) => {
    const navigate = useNavigate();

    return (
        <div className="me-6 text-end flex flex-row items-center justify-end gap-6">
            {/* <button
                onClick={() => navigate(`/human-resources/employee/${row.original.id}/edit`)}
                className="hover:bg-white-blue-300 rounded-full p-1"
            >
                <EditIcon className="text-primery-blue-400" />
            </button> */}
            <button
                onClick={() => navigate(`/programs/program/${row.original.id}`)}
                className="hover:bg-white-blue-300 rounded-full p-1"
            >
                <ViewIcon className="text-primery-blue-400" />
            </button>
        </div>
    );
};

export const columns: ColumnDef<Program>[] = [
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    البرامج 
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.name}</p>

            </div>
        ),
    },
    {
        id: 'department',
        accessorFn: (row) => row.department?.name ?? '',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                القسم
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {row.original.department?.name ?? '-'}
            </div>
        ),
    },
    {
        id: 'seats',
        accessorKey: 'target_number',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                     المقاعد
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.target_number ?? '-'}
                </div>
            );
        },
    },
    {
        id: 'duration',
        accessorKey: 'description',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    مده البرنامج
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.description ?? row.original.job?.name ?? '-'}
                </div>
            );
        },
    },
    {
        id: 'completion',
        accessorKey: 'applicants_number',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    نسبة الاكتمال
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.applicants_number ?? '-'}
                </div>
            );
        },
    },
    {
        accessorKey: 'status',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    حالة 
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-xs text-[#22AD5C] font-medium tracking-normal leading-[115%]">
                    <p className="border border-[#22AD5C] p-1 w-fit rounded-sm">{row.original.status}</p>
                </div>
            );
        },
    },
  
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
